INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22601, 'តាមនិយមន័យ អេលីបគឺជាសំណុំចំណុច \(P\) ក្នុងប្លង់ ដែលផលបូកចម្ងាយពី \(P\) ទៅកំណុំទាំងពីរ \(F_1, F_2\) ស្មើនឹងអ្វី?', NULL, '["ចំនួនថេរ \\(2a\\)", "ផលសងថេរ \\(2a\\)", "ពាក់កណ្ដាលអ័ក្សតូច \\(b\\)", "ចំនួនថេរ \\(2c\\)"]', 0, NULL, 1, 'mcq', 'តាមនិយមន័យ គ្រប់ចំណុច \(P\) លើអេលីបផ្ទៀងផ្ទាត់ \(PF_1 + PF_2 = 2a\) (ប្រវែងអ័ក្សធំ) ។', 'និយមន័យអេលីប', 'easy', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22602, 'រកប្រវែងអ័ក្សធំនៃអេលីប \(\frac{x^2}{25} + \frac{y^2}{9} = 1\) ។', NULL, '["\\(6\\)", "\\(5\\)", "\\(10\\)", "\\(8\\)"]', 2, NULL, 1, 'mcq', 'ដោយ \(a^2 = 25 \Rightarrow a = 5\) នោះប្រវែងអ័ក្សធំគឺ \(2a = 10\) ។', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22603, 'រកកូអរដោនេផ្ចិត \(I(h, k)\) នៃអេលីប \(\frac{(x - 3)^2}{16} + \frac{(y + 2)^2}{9} = 1\) ។', NULL, '["\\(I(3, 2)\\)", "\\(I(3, -2)\\)", "\\(I(-3, 2)\\)", "\\(I(4, 3)\\)"]', 1, NULL, 1, 'mcq', 'ប្រៀបធៀបនឹង \(\frac{(x - h)^2}{a^2} + \frac{(y - k)^2}{b^2} = 1\) បាន \(I(3, -2)\) ។', 'សមីការអេលីបដែលមានផ្ចិត I(h, k)', 'easy', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22604, 'រកអ៊ុចសង់ទ្រីស៊ីតេ \(e\) នៃអេលីប \(\frac{x^2}{25} + \frac{y^2}{9} = 1\) ។', NULL, '["\\(\\frac{9}{25}\\)", "\\(\\frac{4}{5}\\)", "\\(\\frac{5}{4}\\)", "\\(\\frac{3}{5}\\)"]', 1, NULL, 1, 'mcq', 'គេមាន \(a = 5, c = \sqrt{25 - 9} = 4\) ដូច្នេះ \(e = \frac{c}{a} = \frac{4}{5}\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអេលីប', 'easy', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22605, 'ចំពោះអេលីបដែលមានកន្លះអ័ក្សធំ \(a\) កន្លះអ័ក្សតូច \(b\) និងចម្ងាយពីផ្ចិតទៅកំណុំ \(c\) តើទំនាក់ទំនងណាត្រឹមត្រូវ?', NULL, '["\\(c^2 = a^2 - b^2\\)", "\\(c^2 = a^2 + b^2\\)", "\\(a^2 = b^2 - c^2\\)", "\\(b^2 = a^2 + c^2\\)"]', 0, NULL, 1, 'mcq', 'ក្នុងត្រីកោណកែងផ្គុំដោយផ្ចិត កំណុំ និងចុងអ័ក្សតូច គេបាន \(a^2 = b^2 + c^2\) ឬ \(c^2 = a^2 - b^2\) ។', 'និយមន័យអេលីប', 'easy', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22606, 'រកប្រវែងអ័ក្សតូចនៃអេលីប \(\frac{x^2}{16} + \frac{y^2}{49} = 1\) ។', NULL, '["\\(14\\)", "\\(4\\)", "\\(8\\)", "\\(7\\)"]', 2, NULL, 1, 'mcq', 'ដោយ \(49 > 16\) បាន \(b^2 = 16 \Rightarrow b = 4\) ដូច្នេះប្រវែងអ័ក្សតូចគឺ \(2b = 8\) ។', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22607, 'តើអ៊ុចសង់ទ្រីស៊ីតេ \(e\) នៃអេលីបស្ថិតក្នុងចន្លោះណា?', NULL, '["\\(0 < e < 1\\)", "\\(e > 1\\)", "\\(e = 1\\)", "\\(-1 < e < 0\\)"]', 0, NULL, 1, 'mcq', 'ដោយ \(0 < c < a\) នោះ \(0 < \frac{c}{a} < 1\) គឺ \(0 < e < 1\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអេលីប', 'easy', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22608, 'រកកូអរដោនេកំណុំទាំងពីរនៃអេលីប \(\frac{x^2}{25} + \frac{y^2}{16} = 1\) ។', NULL, '["\\((\\pm 4, 0)\\)", "\\((\\pm 3, 0)\\)", "\\((\\pm 5, 0)\\)", "\\((0, \\pm 3)\\)"]', 1, NULL, 1, 'mcq', 'គេមាន \(a^2 = 25, b^2 = 16 \Rightarrow c = \sqrt{25 - 16} = 3\) ។ ដោយអ័ក្សធំលើ \(Ox\) កំណុំគឺ \((\pm 3, 0)\) ។', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22609, 'រកកូអរដោនេកំពូលទាំងពីរនៃអេលីប \(\frac{x^2}{25} + \frac{y^2}{169} = 1\) ។', NULL, '["\\((0, \\pm 12)\\)", "\\((\\pm 13, 0)\\)", "\\((0, \\pm 5)\\)", "\\((0, \\pm 13)\\)"]', 3, NULL, 1, 'mcq', 'ដោយ \(a^2 = 169 \Rightarrow a = 13\) និងអ័ក្សធំនៅលើ \(Oy\) កំពូលគឺ \((0, \pm 13)\) ។', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22610, 'រកសមីការស្ដង់ដានៃអេលីបដែលមានផ្ចិត \(O(0, 0)\) កំពូល \((\pm 5, 0)\) និងកំណុំ \((\pm 3, 0)\) ។', NULL, '["\\(\\frac{x^2}{5} + \\frac{y^2}{4} = 1\\)", "\\(\\frac{x^2}{16} + \\frac{y^2}{25} = 1\\)", "\\(\\frac{x^2}{25} + \\frac{y^2}{9} = 1\\)", "\\(\\frac{x^2}{25} + \\frac{y^2}{16} = 1\\)"]', 3, NULL, 1, 'mcq', 'គេមាន \(a = 5, c = 3 \Rightarrow b^2 = 25 - 9 = 16\) ។ ដោយអ័ក្សធំលើ \(Ox\) បាន \(\frac{x^2}{25} + \frac{y^2}{16} = 1\) ។', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22611, 'រកកូអរដោនេកំណុំទាំងពីរនៃអេលីប \(25x^2 + 169y^2 = 4\,225\) ។', NULL, '["\\((\\pm 12, 0)\\)", "\\((0, \\pm 12)\\)", "\\((\\pm 5, 0)\\)", "\\((\\pm 13, 0)\\)"]', 0, NULL, 2, 'mcq', 'ចែកនឹង \(4\,225\) បាន \(\frac{x^2}{169} + \frac{y^2}{25} = 1\) ។ គេបាន \(c = \sqrt{169 - 25} = 12\) ដូច្នេះ \((\pm 12, 0)\) ។', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'medium', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22612, 'រកកូអរដោនេកំពូលទាំងពីរនៃអេលីប \(\frac{(x + 1)^2}{64} + \frac{(y - 3)^2}{289} = 1\) ។', NULL, '["\\((-18, 3)\\) និង \\((16, 3)\\)", "\\((-1, -12)\\) និង \\((-1, 18)\\)", "\\((-1, -14)\\) និង \\((-1, 20)\\)", "\\((-9, 3)\\) និង \\((7, 3)\\)"]', 2, NULL, 2, 'mcq', 'ផ្ចិត \(I(-1, 3)\) និង \(a = \sqrt{289} = 17\) (អ័ក្សធំឈរ) ។ កំពូលគឺ \((-1, 3 \pm 17)\) គឺ \((-1, -14)\) និង \((-1, 20)\) ។', 'សមីការអេលីបដែលមានផ្ចិត I(h, k)', 'medium', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22613, 'រកអ៊ុចសង់ទ្រីស៊ីតេនៃអេលីប \(\frac{(x - 1)^2}{289} + \frac{(y + 4)^2}{225} = 1\) ។', NULL, '["\\(\\frac{8}{15}\\)", "\\(\\frac{15}{17}\\)", "\\(\\frac{12}{17}\\)", "\\(\\frac{8}{17}\\)"]', 3, NULL, 2, 'mcq', 'គេមាន \(a = 17, b = 15 \Rightarrow c = \sqrt{289 - 225} = 8\) ដូច្នេះ \(e = \frac{c}{a} = \frac{8}{17}\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអេលីប', 'medium', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22614, 'តាង \(P\) ជាចំណុចមួយនៅលើអេលីប \(9x^2 + 25y^2 = 225\) ដែលមានកំណុំ \(F_1, F_2\) ។ រកផលបូក \(PF_1 + PF_2\) ។', NULL, '["\\(5\\)", "\\(8\\)", "\\(6\\)", "\\(10\\)"]', 3, NULL, 2, 'mcq', 'សមីការស្ដង់ដាគឺ \(\frac{x^2}{25} + \frac{y^2}{9} = 1\) មាន \(a = 5\) ដូច្នេះ \(PF_1 + PF_2 = 2a = 10\) ។', 'និយមន័យអេលីប', 'medium', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22615, 'រកសមីការស្ដង់ដានៃអេលីបដែលមានផ្ចិត \((0, 0)\) កំណុំ \((0, \pm 4)\) និងអ័ក្សធំប្រវែង \(10\) ។', NULL, '["\\(\\frac{x^2}{9} + \\frac{y^2}{25} = 1\\)", "\\(\\frac{x^2}{16} + \\frac{y^2}{25} = 1\\)", "\\(\\frac{x^2}{25} + \\frac{y^2}{9} = 1\\)", "\\(\\frac{x^2}{25} + \\frac{y^2}{16} = 1\\)"]', 0, NULL, 2, 'mcq', 'គេមាន \(2a = 10 \Rightarrow a = 5, c = 4 \Rightarrow b^2 = 25 - 16 = 9\) ។ ដោយកំណុំលើ \(Oy\) បាន \(\frac{x^2}{9} + \frac{y^2}{25} = 1\) ។', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'medium', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22616, 'រកកូអរដោនេកំណុំទាំងពីរនៃអេលីប \(\frac{(x - 2)^2}{25} + \frac{(y + 1)^2}{169} = 1\) ។', NULL, '["\\((2, -14)\\) និង \\((2, 12)\\)", "\\((2, -6)\\) និង \\((2, 4)\\)", "\\((-10, -1)\\) និង \\((14, -1)\\)", "\\((2, -13)\\) និង \\((2, 11)\\)"]', 3, NULL, 2, 'mcq', 'ផ្ចិត \(I(2, -1)\) និង \(c = \sqrt{169 - 25} = 12\) (អ័ក្សធំឈរ) ។ កំណុំគឺ \((2, -1 \pm 12)\) ។', 'សមីការអេលីបដែលមានផ្ចិត I(h, k)', 'medium', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22617, 'រកសមីការស្ដង់ដានៃអេលីបដែលមានកំណុំ \((-1, 1)\) និង \((-1, 9)\) ហើយមានអ៊ុចសង់ទ្រីស៊ីតេ \(e = \frac{4}{5}\) ។', NULL, '["\\(\\frac{(x + 1)^2}{25} + \\frac{(y - 5)^2}{9} = 1\\)", "\\(\\frac{(x + 1)^2}{16} + \\frac{(y - 5)^2}{25} = 1\\)", "\\(\\frac{(x + 1)^2}{9} + \\frac{(y - 5)^2}{25} = 1\\)", "\\(\\frac{(x - 1)^2}{9} + \\frac{(y + 5)^2}{25} = 1\\)"]', 2, NULL, 2, 'mcq', 'ផ្ចិត \(I(-1, 5)\) និង \(c = 4\) ។ ដោយ \(e = \frac{c}{a} = \frac{4}{5} \Rightarrow a = 5, b = 3\) (អ័ក្សធំឈរ) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអេលីប', 'medium', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22618, 'រកសមីការអេលីបដែលមានផ្ចិត \((0, 0)\) អ័ក្សធំនៅលើ \(Ox\) និងកាត់តាមចំណុច \((5, 0)\) និង \(\left(3, \frac{16}{5}\right)\) ។', NULL, '["\\(\\frac{x^2}{25} + \\frac{y^2}{16} = 1\\)", "\\(\\frac{x^2}{16} + \\frac{y^2}{25} = 1\\)", "\\(\\frac{x^2}{25} + \\frac{y^2}{12} = 1\\)", "\\(\\frac{x^2}{25} + \\frac{y^2}{9} = 1\\)"]', 0, NULL, 2, 'mcq', 'ជំនួស \((5, 0)\) បាន \(a^2 = 25\) ។ ជំនួស \(\left(3, \frac{16}{5}\right)\) បាន \(\frac{9}{25} + \frac{256}{25 b^2} = 1 \Rightarrow b^2 = 16\) ។', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'medium', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22619, 'រកកូអរដោនេផ្ចិតនៃអេលីប \(9x^2 + 25y^2 - 36x + 50y - 164 = 0\) ។', NULL, '["\\(I(2, 1)\\)", "\\(I(2, -1)\\)", "\\(I(-2, 1)\\)", "\\(I(-2, -1)\\)"]', 1, NULL, 2, 'mcq', 'បំប្លែងជាការេពេញ៖ \(9(x - 2)^2 + 25(y + 1)^2 = 225\) ដូច្នេះផ្ចិតគឺ \(I(2, -1)\) ។', 'សមីការអេលីបដែលមានផ្ចិត I(h, k)', 'medium', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22620, 'រកអ៊ុចសង់ទ្រីស៊ីតេនៃអេលីប \(16x^2 + 25y^2 - 64x + 50y - 311 = 0\) ។', NULL, '["\\(\\frac{5}{8}\\)", "\\(\\frac{3}{5}\\)", "\\(\\frac{3}{4}\\)", "\\(\\frac{4}{5}\\)"]', 1, NULL, 2, 'mcq', 'បំប្លែងបាន \(\frac{(x - 2)^2}{25} + \frac{(y + 1)^2}{16} = 1\) មាន \(a = 5, b = 4, c = 3\) ដូច្នេះ \(e = \frac{3}{5}\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអេលីប', 'medium', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22621, 'រកប្រវែងអង្កត់កាត់កំណុំកែងអ័ក្សធំ \(\frac{2b^2}{a}\) នៃអេលីប \(\frac{x^2}{25} + \frac{y^2}{9} = 1\) ។', NULL, '["\\(\\frac{9}{5}\\)", "\\(\\frac{32}{5}\\)", "\\(\\frac{18}{5}\\)", "\\(6\\)"]', 2, NULL, 2, 'mcq', 'គេមាន \(a = 5, b^2 = 9\) ដូច្នេះប្រវែងអង្កត់កាត់កំណុំគឺ \(\frac{2b^2}{a} = \frac{18}{5}\) ។', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'medium', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22622, 'រកប្រវែងអ័ក្សធំនៃអេលីប \(25x^2 + 9y^2 + 100x - 54y - 44 = 0\) ។', NULL, '["\\(6\\)", "\\(5\\)", "\\(8\\)", "\\(10\\)"]', 3, NULL, 2, 'mcq', 'សរសេរជា \(\frac{(x + 2)^2}{9} + \frac{(y - 3)^2}{25} = 1\) បាន \(a = 5\) ដូច្នេះអ័ក្សធំមានប្រវែង \(2a = 10\) ។', 'សមីការអេលីបដែលមានផ្ចិត I(h, k)', 'medium', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22623, 'រកសមីការស្ដង់ដានៃអេលីបដែលមានកំពូល \((-2, 3)\) និង \((8, 3)\) ហើយអ័ក្សតូចមានប្រវែង \(6\) ។', NULL, '["\\(\\frac{(x - 3)^2}{25} + \\frac{(y - 3)^2}{36} = 1\\)", "\\(\\frac{(x + 3)^2}{25} + \\frac{(y - 3)^2}{9} = 1\\)", "\\(\\frac{(x - 3)^2}{25} + \\frac{(y - 3)^2}{9} = 1\\)", "\\(\\frac{(x - 3)^2}{9} + \\frac{(y - 3)^2}{25} = 1\\)"]', 2, NULL, 2, 'mcq', 'ផ្ចិតនៅចំណុចកណ្ដាល \(I(3, 3)\) មាន \(a = 5, b = 3\) និងអ័ក្សធំដេក ដូច្នេះ \(\frac{(x - 3)^2}{25} + \frac{(y - 3)^2}{9} = 1\) ។', 'សមីការអេលីបដែលមានផ្ចិត I(h, k)', 'medium', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22624, 'សមីការដឺក្រេទី 2 \(Ax^2 + By^2 + Cx + Dy + E = 0\) (ដែលមិនទទេ) ជាសមីការទូទៅនៃអេលីប លុះត្រាតែ \(A, B\) ផ្ទៀងផ្ទាត់លក្ខខណ្ឌណា?', NULL, '["\\(A \\cdot B < 0\\)", "\\(A \\cdot B > 0\\) និង \\(A \\neq B\\)", "\\(A \\cdot B = 0\\)", "\\(A = B\\)"]', 1, NULL, 2, 'mcq', 'សមីការទូទៅនៃអេលីបត្រូវមាន \(A\) និង \(B\) សញ្ញាដូចគ្នា (\(A \cdot B > 0\)) និង \(A \neq B\) (បើ \(A = B\) ជារង្វង់) ។', 'សមីការអេលីបដែលមានផ្ចិត I(h, k)', 'medium', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22625, 'រកសមីការសំណុំចំណុច \(M(x, y)\) ដែលមានផលបូកចម្ងាយពី \(F_1(5, -2)\) និង \(F_2(-5, -2)\) ស្មើនឹង \(26\) ។', NULL, '["\\(\\frac{x^2}{144} + \\frac{(y + 2)^2}{169} = 1\\)", "\\(\\frac{x^2}{169} + \\frac{(y - 2)^2}{144} = 1\\)", "\\(\\frac{x^2}{169} + \\frac{(y + 2)^2}{144} = 1\\)", "\\(\\frac{x^2}{169} + \\frac{(y + 2)^2}{25} = 1\\)"]', 2, NULL, 3, 'mcq', 'ផ្ចិត \(I(0, -2)\) មាន \(c = 5, 2a = 26 \Rightarrow a = 13\) និង \(b^2 = 169 - 25 = 144\) ។', 'និយមន័យអេលីប', 'hard', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22626, 'អេលីបមួយមានផ្ចិត \(I(2, -1)\) កំណុំមួយនៅ \((2, 14)\) និងកាត់តាមចំណុចចុងអ័ក្សតូច \((10, -1)\) ។ រកសមីការស្ដង់ដារបស់វា ។', NULL, '["\\(\\frac{(x - 2)^2}{64} + \\frac{(y + 1)^2}{289} = 1\\)", "\\(\\frac{(x - 2)^2}{225} + \\frac{(y + 1)^2}{289} = 1\\)", "\\(\\frac{(x - 2)^2}{289} + \\frac{(y + 1)^2}{64} = 1\\)", "\\(\\frac{(x - 2)^2}{64} + \\frac{(y + 1)^2}{225} = 1\\)"]', 0, NULL, 3, 'mcq', 'គេមាន \(c = 14 - (-1) = 15, b = 10 - 2 = 8 \Rightarrow a = \sqrt{8^2 + 15^2} = 17\) ដោយអ័ក្សធំឈរ ។', 'សមីការអេលីបដែលមានផ្ចិត I(h, k)', 'hard', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22627, 'រកតម្លៃ \(k\) (\(0 < k < 25\)) ដើម្បីឱ្យអេលីប \(\frac{x^2}{25} + \frac{y^2}{k} = 1\) មានអ៊ុចសង់ទ្រីស៊ីតេ \(e = \frac{4}{5}\) ។', NULL, '["\\(16\\)", "\\(9\\)", "\\(12\\)", "\\(4\\)"]', 1, NULL, 3, 'mcq', 'គេមាន \(a = 5, c = e a = 4\) ដូច្នេះ \(k = b^2 = a^2 - c^2 = 25 - 16 = 9\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអេលីប', 'hard', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22628, 'ចំណុច \(P\) ស្ថិតនៅលើអេលីប \(\frac{x^2}{100} + \frac{y^2}{36} = 1\) និងមានចម្ងាយពីកំណុំ \(F_1\) ស្មើ \(7\) ។ រកចម្ងាយ \(PF_2\) ទៅកំណុំមួយទៀត ។', NULL, '["\\(17\\)", "\\(9\\)", "\\(13\\)", "\\(10\\)"]', 2, NULL, 3, 'mcq', 'គេមាន \(a = 10 \Rightarrow PF_1 + PF_2 = 2a = 20\) ដូច្នេះ \(PF_2 = 20 - 7 = 13\) ។', 'និយមន័យអេលីប', 'hard', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22629, 'រកចម្ងាយរវាងកំណុំទាំងពីរ \(F_1F_2\) នៃអេលីប \(4x^2 + 9y^2 - 16x + 54y + 61 = 0\) (គិតជាតម្លៃរ៉ាឌីកាល់) ។', NULL, '["\\(2\\sqrt{5}\\)", "\\(2\\sqrt{13}\\)", "\\(6\\)", "\\(\\sqrt{5}\\)"]', 0, NULL, 3, 'mcq', 'បំប្លែងបាន \(\frac{(x - 2)^2}{9} + \frac{(y + 3)^2}{4} = 1\) មាន \(c = \sqrt{9 - 4} = \sqrt{5}\) ដូច្នេះ \(F_1F_2 = 2c = 2\sqrt{5}\) ។', 'សមីការអេលីបដែលមានផ្ចិត I(h, k)', 'hard', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22630, 'រកសមីការស្ដង់ដានៃអេលីបដែលមានផ្ចិត \(I(3, -2)\) អ័ក្សធំឈរ អ័ក្សតូចប្រវែង \(10\) និងអ៊ុចសង់ទ្រីស៊ីតេ \(e = \frac{12}{13}\) ។', NULL, '["\\(\\frac{(x + 3)^2}{25} + \\frac{(y - 2)^2}{169} = 1\\)", "\\(\\frac{(x - 3)^2}{25} + \\frac{(y + 2)^2}{144} = 1\\)", "\\(\\frac{(x - 3)^2}{169} + \\frac{(y + 2)^2}{25} = 1\\)", "\\(\\frac{(x - 3)^2}{25} + \\frac{(y + 2)^2}{169} = 1\\)"]', 3, NULL, 3, 'mcq', 'គេមាន \(b = 5\) និង \(c = \frac{12}{13}a\) ។ តាម \(a^2 - c^2 = b^2\) បាន \(\frac{25}{169}a^2 = 25 \Rightarrow a = 13\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអេលីប', 'hard', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22631, 'តាង \(P\) ជាចំណុចមួយនៅលើអេលីប \(\frac{x^2}{169} + \frac{y^2}{144} = 1\) មិននៅលើអ័ក្សធំ ។ រកបរិមាត្រនៃត្រីកោណ \(PF_1F_2\) ។', NULL, '["\\(50\\)", "\\(36\\)", "\\(26\\)", "\\(38\\)"]', 1, NULL, 3, 'mcq', 'បរិមាត្រ \(PF_1 + PF_2 + F_1F_2 = 2a + 2c\) ។ ដោយ \(a = 13, b = 12, c = 5\) បាន \(2(13) + 2(5) = 36\) ។', 'និយមន័យអេលីប', 'hard', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Evaluate');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-6f94bb501e.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22632, 'ភពមួយគោចរជុំវិញព្រះអាទិត្យតាមគន្លងអេលីប \(\frac{x^2}{25} + \frac{y^2}{16} = 1\) (គិតជា AU) ដោយព្រះអាទិត្យស្ថិតនៅកំណុំខាងស្ដាំ \(F_1(c, 0)\) ។ រកចម្ងាយជិតបំផុតពីភពទៅព្រះអាទិត្យ ។', 'g12sc-6f94bb501e.svg', '["\\(8\\text{ AU}\\)", "\\(4\\text{ AU}\\)", "\\(3\\text{ AU}\\)", "\\(2\\text{ AU}\\)"]', 3, NULL, 3, 'mcq', 'គេមាន \(a = 5, b = 4 \Rightarrow c = 3\) ។ ចម្ងាយជិតបំផុតគឺ \(a - c = 5 - 3 = 2\text{ AU}\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអេលីប', 'pisa', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-2f51f6d3e9.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22633, 'សាលខ្សឹបសំឡេងរាងអេលីបមួយមានប្រវែងបណ្ដោយ \(26\text{ m}\) និងទទឹង \(10\text{ m}\) ។ ដើម្បីខ្សឹបសំឡេងឮច្បាស់ពីកំណុំមួយទៅកំណុំមួយទៀត តើមនុស្សពីរនាក់ត្រូវឈរនៅចម្ងាយប៉ុន្មានម៉ែត្រពីគ្នា?', 'g12sc-2f51f6d3e9.svg', '["\\(24\\text{ m}\\)", "\\(20\\text{ m}\\)", "\\(12\\text{ m}\\)", "\\(16\\text{ m}\\)"]', 0, NULL, 3, 'mcq', 'គេមាន \(a = 13, b = 5 \Rightarrow c = \sqrt{169 - 25} = 12\text{ m}\) ដូច្នេះចម្ងាយរវាងកំណុំទាំងពីរគឺ \(2c = 24\text{ m}\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអេលីប', 'pisa', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-f86a2c802b.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22634, 'ស្ពានកោងរាងកន្លះអេលីបមួយមានប្រវែងកំណោង \(20\text{ m}\) និងកម្ពស់អតិបរមានៅចំណុចកណ្ដាល \(6\text{ m}\) ។ រកកម្ពស់កំណោងស្ពានត្រង់ចម្ងាយ \(6\text{ m}\) ពីចំណុចកណ្ដាល ។', 'g12sc-f86a2c802b.svg', '["\\(3.6\\text{ m}\\)", "\\(5.2\\text{ m}\\)", "\\(4.8\\text{ m}\\)", "\\(4.0\\text{ m}\\)"]', 2, NULL, 3, 'mcq', 'សមីការគឺ \(\frac{x^2}{100} + \frac{y^2}{36} = 1\) ។ ជំនួស \(x = 6\) បាន \(\frac{y^2}{36} = \frac{64}{100} \Rightarrow y = 4.8\text{ m}\) ។', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'pisa', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
