INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22635, 'សួនច្បាររាងអេលីបមួយមានកន្លះអ័ក្សធំ \(17\text{ m}\) និងកន្លះអ័ក្សតូច \(8\text{ m}\) ។ រកអ៊ុចសង់ទ្រីស៊ីតេនៃសួនច្បាររាងអេលីបនេះ ។', 'g12sc-daaf677a17.svg', '["\\(\\frac{9}{17}\\)", "\\(\\frac{8}{17}\\)", "\\(\\frac{8}{15}\\)", "\\(\\frac{15}{17}\\)"]', 3, NULL, 3, 'mcq', 'គេមាន \(c = \sqrt{17^2 - 8^2} = 15\text{ m}\) ដូច្នេះ \(e = \frac{c}{a} = \frac{15}{17}\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអេលីប', 'pisa', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-fe5f3b7fac.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22636, 'តុអាហាររាងអេលីបមួយមានប្រវែងបណ្ដោយ \(2.6\text{ m}\) និងចម្ងាយរវាងកំណុំទាំងពីរ \(2.4\text{ m}\) ។ រកទទឹងអតិបរមានៃតុអាហារនេះ ។', 'g12sc-fe5f3b7fac.svg', '["\\(1.2\\text{ m}\\)", "\\(1.0\\text{ m}\\)", "\\(0.5\\text{ m}\\)", "\\(2.0\\text{ m}\\)"]', 1, NULL, 3, 'mcq', 'គេមាន \(a = 1.3\text{ m}, c = 1.2\text{ m} \Rightarrow b = \sqrt{1.69 - 1.44} = 0.5\text{ m}\) ដូច្នេះទទឹងគឺ \(2b = 1.0\text{ m}\) ។', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'pisa', 1, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22637, 'គេមានអេលីប \(\frac{x^2}{25} + \frac{y^2}{16} = 1\) ។ រកផ្ចិត កំពូលទាំងពីរ កំណុំទាំងពីរ ប្រវែងអ័ក្សធំ អ័ក្សតូច និងអ៊ុចសង់ទ្រីស៊ីតេ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ផ្ចិតនៅគល់អ័ក្សកូអរដោនេ \(I(0, 0)\) ហើយអ័ក្សធំស្ថិតនៅលើអ័ក្ស \(Ox\) (1 ពិន្ទុ)
កំណត់ \(a = 5, b = 4\) បានប្រវែងអ័ក្សធំ \(2a = 10\) និងអ័ក្សតូច \(2b = 8\) (1 ពិន្ទុ)
គណនា \(c = \sqrt{a^2 - b^2} = \sqrt{25 - 16} = 3\) (1 ពិន្ទុ)
កំពូលគឺ \(V_1(-5, 0), V_2(5, 0)\) និងកំណុំគឺ \(F_1(-3, 0), F_2(3, 0)\) (1 ពិន្ទុ)
អ៊ុចសង់ទ្រីស៊ីតេគឺ \(e = \frac{c}{a} = \frac{3}{5} = 0.6\) ។ (1 ពិន្ទុ)', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'easy', 0, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22638, 'បំប្លែងសមីការអេលីប \(9x^2 + 25y^2 - 18x + 100y - 116 = 0\) ជាទម្រង់ស្ដង់ដា រួចរកផ្ចិត កំពូល កំណុំ និងអ៊ុចសង់ទ្រីស៊ីតេ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ផ្ដុំតួជាការេពេញ៖ \(9(x^2 - 2x + 1) + 25(y^2 + 4y + 4) = 116 + 9 + 100 = 225\) (1 ពិន្ទុ)
ចែកនឹង \(225\) បានទម្រង់ស្ដង់ដា \(\frac{(x - 1)^2}{25} + \frac{(y + 2)^2}{9} = 1\) (1 ពិន្ទុ)
ផ្ចិតគឺ \(I(1, -2)\) មាន \(a = 5, b = 3\) និង \(c = \sqrt{25 - 9} = 4\) (1 ពិន្ទុ)
កំពូលគឺ \(V(1 \pm 5, -2) \Rightarrow (-4, -2), (6, -2)\) និងកំណុំ \(F(1 \pm 4, -2) \Rightarrow (-3, -2), (5, -2)\) (1 ពិន្ទុ)
អ៊ុចសង់ទ្រីស៊ីតេគឺ \(e = \frac{c}{a} = \frac{4}{5}\) ។ (1 ពិន្ទុ)', 'សមីការអេលីបដែលមានផ្ចិត I(h, k)', 'medium', 0, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22639, 'រកសមីការស្ដង់ដានៃអេលីបដែលមានកំណុំ \((0, \pm 12)\) និងអ័ក្សធំមានប្រវែង \(26\) រួចរកកន្លះអ័ក្សតូច និងអ៊ុចសង់ទ្រីស៊ីតេ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ដោយកំណុំ \((0, \pm 12)\) ស្ថិតលើ \(Oy\) ផ្ចិតគឺ \(I(0, 0)\) និង \(c = 12\) (1 ពិន្ទុ)
អ័ក្សធំប្រវែង \(2a = 26 \Rightarrow a = 13\) (1 ពិន្ទុ)
គណនា \(b^2 = a^2 - c^2 = 169 - 144 = 25 \Rightarrow b = 5\) (1 ពិន្ទុ)
សមីការស្ដង់ដានៃអេលីបគឺ \(\frac{x^2}{25} + \frac{y^2}{169} = 1\) (1 ពិន្ទុ)
អ៊ុចសង់ទ្រីស៊ីតេគឺ \(e = \frac{c}{a} = \frac{12}{13}\) ។ (1 ពិន្ទុ)', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'medium', 0, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22640, 'រកសមីការស្ដង់ដានៃអេលីបដែលមានកំពូល \((-1, -15)\) និង \((-1, 19)\) ហើយកំណុំ \((-1, -13)\) និង \((-1, 17)\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ផ្ចិតនៅចំណុចកណ្ដាល៖ \(h = -1, k = \frac{-15 + 19}{2} = 2 \Rightarrow I(-1, 2)\) (1 ពិន្ទុ)
អ័ក្សធំស្របនឹង \(Oy\) ដោយ \(a = 19 - 2 = 17\) និង \(c = 17 - 2 = 15\) (1 ពិន្ទុ)
គណនា \(b^2 = a^2 - c^2 = 17^2 - 15^2 = 289 - 225 = 64\) (1 ពិន្ទុ)
ជំនួសក្នុងទម្រង់ \(\frac{(x - h)^2}{b^2} + \frac{(y - k)^2}{a^2} = 1\) (1 ពិន្ទុ)
សមីការស្ដង់ដាគឺ \(\frac{(x + 1)^2}{64} + \frac{(y - 2)^2}{289} = 1\) ។ (1 ពិន្ទុ)', 'សមីការអេលីបដែលមានផ្ចិត I(h, k)', 'medium', 0, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22641, 'រកសមីការស្ដង់ដានៃអេលីបដែលមានផ្ចិត \(O(0, 0)\) អ័ក្សធំនៅលើអ័ក្ស \(Ox\) និងកាត់តាមចំណុច \((5, 0)\) និង \(\left(4, \frac{12}{5}\right)\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរទម្រង់ \(\frac{x^2}{a^2} + \frac{y^2}{b^2} = 1\) (\(a > b > 0\)) (1 ពិន្ទុ)
ជំនួស \((5, 0)\) បាន \(\frac{25}{a^2} = 1 \Rightarrow a^2 = 25\) (1 ពិន្ទុ)
ជំនួស \(\left(4, \frac{12}{5}\right)\) បាន \(\frac{16}{25} + \frac{144}{25 b^2} = 1\) (1 ពិន្ទុ)
ដោះស្រាយរក \(\frac{144}{25 b^2} = \frac{9}{25} \Rightarrow b^2 = 16\) (1 ពិន្ទុ)
ដូច្នេះសមីការស្ដង់ដាគឺ \(\frac{x^2}{25} + \frac{y^2}{16} = 1\) ។ (1 ពិន្ទុ)', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'medium', 0, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22642, 'ដោយប្រើនិយមន័យអេលីប ចូររកសមីការស្ដង់ដានៃសំណុំចំណុច \(M(x, y)\) ដែល \(MF_1 + MF_2 = 10\) ដោយដឹងថា \(F_1(3, 1)\) និង \(F_2(-3, 1)\) រួចរកអ៊ុចសង់ទ្រីស៊ីតេ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ផ្ចិតនៅចំណុចកណ្ដាល \(I\left(\frac{3-3}{2}, \frac{1+1}{2}\right) = I(0, 1)\) (1 ពិន្ទុ)
កំណុំស្ថិតលើបន្ទាត់ដេក \(y = 1\) ដោយ \(c = 3\) និង \(2a = 10 \Rightarrow a = 5\) (1 ពិន្ទុ)
គណនា \(b^2 = a^2 - c^2 = 25 - 9 = 16 \Rightarrow b = 4\) (1 ពិន្ទុ)
សមីការស្ដង់ដាគឺ \(\frac{x^2}{25} + \frac{(y - 1)^2}{16} = 1\) (1 ពិន្ទុ)
អ៊ុចសង់ទ្រីស៊ីតេគឺ \(e = \frac{c}{a} = \frac{3}{5}\) ។ (1 ពិន្ទុ)', 'និយមន័យអេលីប', 'hard', 0, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22643, 'អេលីបមួយមានផ្ចិត \(I(2, -3)\) អ័ក្សធំស្របនឹងអ័ក្សអរដោនេ អ៊ុចសង់ទ្រីស៊ីតេ \(e = \frac{5}{13}\) និងប្រវែងអង្កត់កាត់កំណុំកែងអ័ក្សធំស្មើ \(\frac{288}{13}\) ។ រកសមីការស្ដង់ដារបស់វា ។', NULL, '[]', 0, NULL, 5, 'writing', 'ដោយ \(e = \frac{c}{a} = \frac{5}{13} \Rightarrow c = \frac{5}{13}a\) (1 ពិន្ទុ)
គណនា \(b^2 = a^2 - c^2 = a^2\left(1 - \frac{25}{169}\right) = \frac{144}{169}a^2\) (1 ពិន្ទុ)
ប្រើប្រវែងអង្កត់កាត់កំណុំ \(\frac{2b^2}{a} = \frac{288}{169}a = \frac{288}{13} \Rightarrow a = 13\) (1 ពិន្ទុ)
ទាញបាន \(a^2 = 169\) និង \(b^2 = 144\) (1 ពិន្ទុ)
សមីការស្ដង់ដាគឺ \(\frac{(x - 2)^2}{144} + \frac{(y + 3)^2}{169} = 1\) ។ (1 ពិន្ទុ)', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអេលីប', 'hard', 0, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22644, 'បំប្លែងសមីការ \(169x^2 + 25y^2 + 338x - 150y - 3\,831 = 0\) ជាសមីការស្ដង់ដា រួចរកផ្ចិត កំពូល កំណុំ និងអ៊ុចសង់ទ្រីស៊ីតេ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ផ្ដុំតួជាការេពេញ៖ \(169(x + 1)^2 + 25(y - 3)^2 = 3\,831 + 169 + 225 = 4\,225\) (1 ពិន្ទុ)
ចែកនឹង \(4\,225\) បាន \(\frac{(x + 1)^2}{25} + \frac{(y - 3)^2}{169} = 1\) (1 ពិន្ទុ)
ផ្ចិតគឺ \(I(-1, 3)\) មាន \(a = 13, b = 5, c = \sqrt{169 - 25} = 12\) (1 ពិន្ទុ)
កំពូលគឺ \((-1, -10), (-1, 16)\) និងកំណុំគឺ \((-1, -9), (-1, 15)\) (1 ពិន្ទុ)
អ៊ុចសង់ទ្រីស៊ីតេគឺ \(e = \frac{c}{a} = \frac{12}{13}\) ។ (1 ពិន្ទុ)', 'សមីការអេលីបដែលមានផ្ចិត I(h, k)', 'hard', 0, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22645, 'តាង \(P\) ជាចំណុចមួយនៅលើអេលីប \(\frac{x^2}{25} + \frac{y^2}{9} = 1\) ដែល \(PF_1 \perp PF_2\) ។ គណនាផលគុណ \(PF_1 \cdot PF_2\) និងផ្ទៃក្រឡាត្រីកោណ \(PF_1F_2\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ពីសមីការអេលីប បាន \(a = 5, b = 3, c = 4 \Rightarrow F_1F_2 = 2c = 8\) (1 ពិន្ទុ)
តាមនិយមន័យអេលីប \(PF_1 + PF_2 = 2a = 10\) (1 ពិន្ទុ)
ដោយ \(PF_1 \perp PF_2\) តាមពីតាគ័រ \(PF_1^2 + PF_2^2 = F_1F_2^2 = 64\) (1 ពិន្ទុ)
ប្រើ \((PF_1 + PF_2)^2 - (PF_1^2 + PF_2^2) = 2PF_1 \cdot PF_2 \Rightarrow 100 - 64 = 36 \Rightarrow PF_1 \cdot PF_2 = 18\) (1 ពិន្ទុ)
ផ្ទៃក្រឡាត្រីកោណកែង \(S = \frac{1}{2} PF_1 \cdot PF_2 = 9\) ឯកតាផ្ទៃ ។ (1 ពិន្ទុ)', 'និយមន័យអេលីប', 'hard', 0, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Evaluate');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-d4e8d8f94e.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22646, 'សាលរាងអេលីបមួយមានប្រវែងបណ្ដោយ \(34\text{ m}\) និងទទឹង \(16\text{ m}\) ។ ក. រកសមីការស្ដង់ដា និងទីតាំងកំណុំទាំងពីរ \(F_1, F_2\) ។ ខ. បើរលកសំឡេងចេញពី \(F_1\) ប៉ះជញ្ជាំងត្រង់ \(P\) ហើយចាំងផ្លាតទៅ \(F_2\) តើចម្ងាយសរុបដែលសំឡេងរត់ស្មើប៉ុន្មានម៉ែត្រ?', 'g12sc-d4e8d8f94e.svg', '[]', 0, NULL, 5, 'writing', 'កំណត់ \(a = 17\text{ m}, b = 8\text{ m}\) បានសមីការ \(\frac{x^2}{289} + \frac{y^2}{64} = 1\) (1 ពិន្ទុ)
គណនា \(c = \sqrt{17^2 - 8^2} = \sqrt{289 - 64} = 15\text{ m}\) (1 ពិន្ទុ)
ទីតាំងកំណុំទាំងពីរគឺ \(F_1(15, 0)\) និង \(F_2(-15, 0)\) (1 ពិន្ទុ)
តាមលក្ខណៈចំណាំងផ្លាតនៃអេលីប សំឡេងពី \(F_1\) ត្រូវចាំងផ្លាតទៅ \(F_2\) (1 ពិន្ទុ)
ចម្ងាយសរុប \(PF_1 + PF_2 = 2a = 34\text{ m}\) ។ (1 ពិន្ទុ)', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអេលីប', 'pisa', 0, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
