INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22647, 'ផ្លូវរូងក្រោមដីមួយមានផ្ទៃកាត់រាងកន្លះអេលីប ទទឹងបាត \(10\text{ m}\) និងកម្ពស់អតិបរមានៅចំណុចកណ្ដាល \(4\text{ m}\) ។ ក. រកសមីការអេលីប ។ ខ. តើរថយន្តទទឹង \(6\text{ m}\) និងកម្ពស់ \(3\text{ m}\) អាចបើកកាត់តាមកណ្ដាលផ្លូវរូងបានឬទេ?', 'g12sc-93522bc7ef.svg', '[]', 0, NULL, 5, 'writing', 'កំណត់ \(a = 5\text{ m}, b = 4\text{ m}\) ដោយផ្ចិតនៅគល់ \(O(0, 0)\) (1 ពិន្ទុ)
សមីការអេលីបគឺ \(\frac{x^2}{25} + \frac{y^2}{16} = 1\) (\(y \ge 0\)) (1 ពិន្ទុ)
រថយន្តទទឹង \(6\text{ m}\) ត្រូវនឹង \(x = \pm 3\text{ m}\) (1 ពិន្ទុ)
ជំនួស \(x = 3\) បាន \(\frac{y^2}{16} = 1 - \frac{9}{25} = \frac{16}{25} \Rightarrow y = 3.2\text{ m}\) (1 ពិន្ទុ)
ដោយ \(3.2\text{ m} > 3\text{ m}\) (សល់ចន្លោះ \(0.2\text{ m}\)) ដូច្នេះរថយន្តអាចបើកកាត់បាន ។ (1 ពិន្ទុ)', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'pisa', 0, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Evaluate');
