INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22648, 'ផ្កាយរណបមួយគោចរជុំវិញផែនដីតាមគន្លងអេលីបដោយផែនដីនៅកំណុំ \(F_1(c, 0)\) ។ ចម្ងាយជិតបំផុតពីផ្កាយរណបទៅផ្ចិតផែនដីគឺ \(2 \times 10^3\text{ km}\) និងចម្ងាយឆ្ងាយបំផុតគឺ \(8 \times 10^3\text{ km}\) ។ រកសមីការគន្លង និងអ៊ុចសង់ទ្រីស៊ីតេ ។', 'g12sc-2f7ac60b45.svg', '[]', 0, NULL, 5, 'writing', 'តាងឯកតាគិតជា \(10^3\text{ km}\) គេមានប្រព័ន្ធ \(a - c = 2\) និង \(a + c = 8\) (1 ពិន្ទុ)
បូកសមីការទាំងពីរបាន \(2a = 10 \Rightarrow a = 5\) និង \(c = 3\) (1 ពិន្ទុ)
គណនា \(b^2 = a^2 - c^2 = 25 - 9 = 16 \Rightarrow b = 4\) (1 ពិន្ទុ)
សមីការគន្លងអេលីបគឺ \(\frac{x^2}{25} + \frac{y^2}{16} = 1\) (1 ពិន្ទុ)
អ៊ុចសង់ទ្រីស៊ីតេគឺ \(e = \frac{c}{a} = \frac{3}{5} = 0.6\) ។ (1 ពិន្ទុ)', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអេលីប', 'pisa', 0, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
