INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22649, 'អាងទឹករាងអេលីបមួយមានផ្ចិតនៅគល់ \(O(0, 0)\) អ័ក្សធំនៅលើ \(Oy\) ប្រវែង \(26\text{ m}\) និងក្បាលបាញ់ទឹកពីរស្ថិតនៅកំណុំ \(F_1(0, 5)\) និង \(F_2(0, -5)\) ។ រកសមីការអេលីប ទទឹងអាង និងអ៊ុចសង់ទ្រីស៊ីតេ ។', 'g12sc-379b5fcfd4.svg', '[]', 0, NULL, 5, 'writing', 'ដោយអ័ក្សធំនៅលើ \(Oy\) គេមាន \(2a = 26 \Rightarrow a = 13\text{ m}\) និង \(c = 5\text{ m}\) (1 ពិន្ទុ)
គណនា \(b^2 = a^2 - c^2 = 169 - 25 = 144 \Rightarrow b = 12\text{ m}\) (1 ពិន្ទុ)
ទទឹងអាងទឹកគឺ \(2b = 24\text{ m}\) (1 ពិន្ទុ)
សមីការអេលីបគឺ \(\frac{x^2}{144} + \frac{y^2}{169} = 1\) (1 ពិន្ទុ)
អ៊ុចសង់ទ្រីស៊ីតេគឺ \(e = \frac{c}{a} = \frac{5}{13}\) ។ (1 ពិន្ទុ)', 'សមីការអេលីបដែលមានផ្ចិតនៅគល់ O(0, 0)', 'pisa', 0, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
