INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22650, 'បន្ទប់ចាំងសំឡេងរាងអេលីបមួយមានកំណុំនៅ \(F_2(-12, 0)\) និង \(F_1(12, 0)\) ហើយគែមជញ្ជាំងកាត់តាមចំណុច \((0, 5)\) (ឯកតាជាម៉ែត្រ) ។ ក. រកសមីការបន្ទប់ ។ ខ. រកអ៊ុចសង់ទ្រីស៊ីតេ និងប្រវែងអង្កត់កាត់កំណុំកែងអ័ក្សធំ ។', 'g12sc-4ab98d5e8a.svg', '[]', 0, NULL, 5, 'writing', 'ផ្ចិតគឺ \(O(0, 0)\) ដោយកំណុំលើ \(Ox\) បាន \(c = 12\) និងចំណុច \((0, 5)\) ឱ្យ \(b = 5\) (1 ពិន្ទុ)
គណនា \(a = \sqrt{b^2 + c^2} = \sqrt{25 + 144} = 13\text{ m}\) (1 ពិន្ទុ)
សមីការស្ដង់ដាគឺ \(\frac{x^2}{169} + \frac{y^2}{25} = 1\) (1 ពិន្ទុ)
អ៊ុចសង់ទ្រីស៊ីតេគឺ \(e = \frac{c}{a} = \frac{12}{13}\) (1 ពិន្ទុ)
ប្រវែងអង្កត់កាត់កំណុំកែងអ័ក្សធំគឺ \(\frac{2b^2}{a} = \frac{2 \times 25}{13} = \frac{50}{13}\text{ m}\) ។ (1 ពិន្ទុ)', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអេលីប', 'pisa', 0, '12SC', 'អេលីប', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Create');
